package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.accessibilityservice.AccessibilityServiceInfo;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import java.util.*;import org.json.*;
/** Only disposable synthetic projects. Raw widgets must survive genuine Activity destruction. */
final class ManagerFormChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;final ManagerRotationChecks r;
 ManagerFormChecks(MapAndroidChecks checks){m=checks;v=new ManagerVisualChecks(m);r=new ManagerRotationChecks(m);}
 String error(View view){String result="";if(view instanceof TextView&&!(view instanceof EditText)&&((TextView)view).getCurrentTextColor()==0xffb00020)result=((TextView)view).getText().toString();if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)result+=error(group.getChildAt(i));}return result;}
 String state(){final String[] result={null};m.runOnMainSync(()->{try{View root=m.activeDialogRoot();List<EditText> fields=new ArrayList<>();m.collectInputs(root,fields);List<Spinner> spinners=new ArrayList<>();List<CheckBox> boxes=new ArrayList<>();m.listingWidgets(root,spinners,boxes);JSONObject o=new JSONObject();JSONArray inputs=new JSONArray(),choices=new JSONArray(),checks=new JSONArray();for(EditText input:fields)inputs.put(new JSONArray().put(input.getText().toString()).put(input.getSelectionStart()).put(input.getSelectionEnd()).put(input.hasFocus()));for(Spinner spinner:spinners)choices.put(spinner.getSelectedItemPosition());for(CheckBox box:boxes)checks.put(box.isChecked());o.put("inputs",inputs);o.put("spinners",choices);o.put("checks",checks);o.put("error",error(root));result[0]=o.toString();}catch(Exception e){throw new RuntimeException(e);}});return result[0];}
 void keyboard(int index)throws Exception{m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);EditText field=fields.get(index);field.requestFocus();field.setSelection(3,Math.min(8,field.length()));((InputMethodManager)m.activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(field,InputMethodManager.SHOW_IMPLICIT);});long end=System.currentTimeMillis()+7000;while(v.imeWindows().length()==0&&System.currentTimeMillis()<end)Thread.sleep(100);m.check(v.imeWindows().length()>0,"real IME for form field "+index);}
 void searchDraft()throws Exception{m.click("Поиск и фильтры");m.inputs("QA_Несохранённый 😀");m.runOnMainSync(()->{List<Spinner> spinners=new ArrayList<>();List<CheckBox> boxes=new ArrayList<>();m.listingWidgets(m.activeDialogRoot(),spinners,boxes);m.check(spinners.size()==4&&boxes.size()==2,"search raw controls exist");int[] values={2,2,1,3};for(int i=0;i<4;i++)spinners.get(i).setSelection(values[i]);for(CheckBox box:boxes)box.setChecked(true);});m.waitForIdleSync();keyboard(0);}
 void run()throws Exception{
  Context c=m.getTargetContext();Object store=m.storeClass.getConstructor(Context.class).newInstance(c);long id=-1;AccessibilityServiceInfo info=m.getUiAutomation().getServiceInfo();int flags=info.flags;info.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(info);String oldKeyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();boolean all=true;
  try{Object doc=r.parse(ManagerRotationChecks.XML.getBytes("UTF-8"));m.staticCall("MediaLinks","add",new Class[]{m.codec,org.w3c.dom.Element.class,String.class,String.class,byte[].class},doc,m.element(doc,"point"),"form.jpg","image/jpeg",new byte[]{1,3,5,7});id=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_FORMS_ROTATION");byte[] before=r.xml(r.load(store,id));Map<String,byte[]> assets=new HashMap<>(m.assets(r.load(store,id)));v.shell("settings put secure show_ime_with_hard_keyboard 1");
   for(String kind:new String[]{"search","dates"}){v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);Map<String,?> prefs=new HashMap<>(c.getSharedPreferences("object-manager-view",0).getAll());if(kind.equals("search"))searchDraft();else{m.dateForm(2,"2026-10-01","2026-10-");m.click("Применить");m.waitText("Дата: ГГГГ-ММ-ДД");keyboard(1);}v.snapshot("forms-"+kind+"-before",true,"Применить");String expected=state();Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.waitForIdleSync();Thread.sleep(700);v.snapshot("forms-"+kind+"-after",false);m.check(old!=m.activity&&old.isDestroyed(),"form rotation really destroys Activity: "+kind);String actual=state();boolean restored=expected.equals(actual);v.emit("FORM_STATE kind="+kind+" restored="+restored+" before="+expected+" after="+actual);all&=restored;m.check(prefs.equals(c.getSharedPreferences("object-manager-view",0).getAll()),"rotation does not apply raw filter preferences");m.check(Arrays.equals(before,r.xml(r.load(store,id))),"form recreation does not write KML");r.sameAssets(r.load(store,id),assets);}
   m.check(all,"raw search/date widgets and validation survive Activity recreation");
  }finally{v.finish();info.flags=flags;m.getUiAutomation().setServiceInfo(info);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(oldKeyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+oldKeyboard);if(id>0)m.call(store,"remove",new Class[]{long.class},id);m.call(store,"close",new Class[]{});}
 }
}
